actions.script:
String compName = targetComponent.trim().toLowerCase().replaceAll("[^a-z0-9-]", "")

def normalizeUri = { String rawUri ->
    String cleaned = rawUri.trim()
    if (!cleaned.endsWith(".xml")) cleaned += ".xml"
    if (cleaned.startsWith("component://")) return cleaned

    if (cleaned.startsWith("screen/")) {
        return "component://${compName}/${cleaned}"
    } else {
        return "component://${compName}/screen/${cleaned}"
    }
}

String srcUri = normalizeUri(sourceArtifactUri)
String tgtUri = normalizeUri(targetArtifactUri)

String srcPhysical = "runtime/component/" + srcUri.replace("component://", "")
String tgtPhysical = "runtime/component/" + tgtUri.replace("component://", "")

ec.logger.info("🚚 [MCP /move-artifact] Resolving srcPhysical: ${srcPhysical} -> tgtPhysical: ${tgtPhysical}")

File srcFile = new File(srcPhysical)
if (!srcFile.exists()) {
    ec.message.addError("Source file does not exist on disk: ${srcPhysical}")
    return
}

File tgtFile = new File(tgtPhysical)
tgtFile.getParentFile().mkdirs()

boolean moved = srcFile.renameTo(tgtFile)
if (!moved) {
    tgtFile.text = srcFile.text
    srcFile.delete()
}
ec.logger.info("🚚 [MCP /move-artifact] Successfully relocated file on disk to: ${tgtPhysical}")

String srcQvtPhysical = srcPhysical.replace(".xml", ".qvt.js")
int lastSlashIdx = srcQvtPhysical.lastIndexOf('/')
if (lastSlashIdx != -1) {
    String srcQvtDir = srcQvtPhysical.substring(0, lastSlashIdx)
    String fileName = srcQvtPhysical.substring(lastSlashIdx + 1)
    File srcQvtFile = new File("${srcQvtDir}/assets/${fileName}")

    if (srcQvtFile.exists()) {
        String tgtQvtPhysical = tgtPhysical.replace(".xml", ".qvt.js")
        int tgtSlashIdx = tgtQvtPhysical.lastIndexOf('/')
        String tgtQvtDir = tgtQvtPhysical.substring(0, tgtSlashIdx)
        File tgtQvtFile = new File("${tgtQvtDir}/assets/${fileName}")
        tgtQvtFile.getParentFile().mkdirs()

        srcQvtFile.renameTo(tgtQvtFile)
        ec.logger.info("🚚 [MCP /move-artifact] Relocated companion QVT asset to: ${tgtQvtFile.path}")
    }
}

def art = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", srcUri).one()
if (art) {
    art.artifactPath = tgtUri
    art.update()
    context.agiArtifactId = art.agiArtifactId
}

def buffers = ec.entity.find("org.moqui.ai.WorkspaceBuffer").condition("artifactUri", srcUri).list()
buffers.each { buf ->
    buf.artifactUri = tgtUri
    buf.update()
}

def workEfforts = ec.entity.find("mantle.work.effort.WorkEffort").condition("sourceReferenceId", srcUri).list()
workEfforts.each { we ->
    we.sourceReferenceId = tgtUri
    we.update()
}

context.artifactUri = tgtUri

                String compName = targetComponent.trim().toLowerCase().replaceAll("[^a-z0-9-]", "")
                String rawUri = artifactUri ?: screenPath

                if (!rawUri || rawUri.trim().isEmpty()) {
                    ec.message.addError("Either artifactUri or screenPath must be provided to attach a QVT asset.")
                    return
                }

                String cleaned = rawUri.trim()
                if (!cleaned.endsWith(".xml")) cleaned += ".xml"

                String srcUri
                if (cleaned.startsWith("component://")) {
                    srcUri = cleaned
                } else if (cleaned.startsWith("screen/")) {
                    srcUri = "component://${compName}/${cleaned}"
                } else {
                    srcUri = "component://${compName}/screen/${cleaned}"
                }

                String relPath = srcUri.replace("component://", "")
                String physicalPath = "runtime/component/" + relPath

                File xmlFile = new File(physicalPath)
                if (!xmlFile.exists()) {
                    ec.message.addError("Screen XML file does not exist on disk: ${physicalPath}")
                    return
                }

                String cleanCompName = xmlFile.name.replace(".xml", "")
                int lastSlashIdx = physicalPath.lastIndexOf('/')
                String dirPath = (lastSlashIdx != -1) ? physicalPath.substring(0, lastSlashIdx) : ""

                String qvtPhysical = "${dirPath}/assets/${cleanCompName}.qvt.js"
                String qvtUri = srcUri.substring(0, srcUri.lastIndexOf('/')) + "/assets/${cleanCompName}.qvt.js"

                File qvtFile = new File(qvtPhysical)
                if (!qvtFile.exists()) {
                    qvtFile.getParentFile().mkdirs()
                    String qvtContent = """(function () {
    const ${cleanCompName} = {
        name: '${cleanCompName}',
        template: `
            <div class="q-pa-md bg-slate-900 text-white rounded-borders">
                <div class="text-h6 text-primary">${cleanCompName} Component</div>
                <div class="text-caption text-grey-4">Custom Component Viewport</div>
            </div>
        `,
        data() {
            return {
                title: '${cleanCompName}'
            };
        }
    };

    window.${cleanCompName} = ${cleanCompName};
    if (!window.AgiComponents) window.AgiComponents = {};
    window.AgiComponents['${cleanCompName}'] = ${cleanCompName};
})();
"""
                    qvtFile.text = qvtContent
                    ec.logger.info("📄 [MCP /attach-qvt-asset] Created companion QVT file at ${qvtPhysical}")
                }

                String xmlText = xmlFile.text
                if (!xmlText.contains("AgiComponentEditor")) {
                    xmlText = xmlText.replace("editor=\"AgiScreenEditor\"", "editor=\"AgiComponentEditor\"")
                    if (!xmlText.contains("editor=")) {
                        xmlText = xmlText.replace("<screen ", "<screen editor=\"AgiComponentEditor\" ")
                    }
                }

                String scriptTag = "<script location=\"${qvtUri}\"/>"
                if (!xmlText.contains(scriptTag)) {
                    xmlText = xmlText.replace("require-authentication=\"true\">", "require-authentication=\"true\">\n    " + scriptTag)
                }

                xmlFile.text = xmlText
                ec.logger.info("✏️ [MCP /attach-qvt-asset] Updated ${physicalPath} to include ${scriptTag}")

                def art = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", srcUri).one()
                if (art) {
                    def parentWe = ec.entity.find("mantle.work.effort.WorkEffort")
                            .condition("agiArtifactId", art.agiArtifactId)
                            .condition("workEffortTypeEnumId", "WetIntent")
                            .one()

                    ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([
                        workEffortName: "Attached QVT Asset: " + cleanCompName,
                        parentWorkEffortId: parentWe?.workEffortId,
                        agiArtifactId: art.agiArtifactId,
                        sourceReferenceId: qvtUri,
                        workEffortTypeEnumId: "WetIntent"
                    ]).call()
                }

                context.qvtAssetUri = qvtUri
                context.artifactUri = srcUri

def resRef = ec.resource.getLocationReference(artifactUri)
if (!resRef || !resRef.exists) {
    ec.message.addError("Target artifact XML file does not exist at ${artifactUri}")
    return
}

String xmlText = resRef.getText()
def rootNode = new XmlSlurper(false, false).parseText(xmlText)

String newId = containerId ?: "${containerType}-${System.currentTimeMillis()}"

def targetParent = rootNode.depthFirst().find { it.@id == parentContainerId }
if (!targetParent) {
    targetParent = rootNode.widgets[0]
}

if (!targetParent) {
    ec.message.addError("Could not locate parent container '${parentContainerId}' or <widgets> root in ${artifactUri}")
    return
}

def sb = new StringBuilder()
if (containerType == "section") {
    sb.append("<section name=\"${newId}\"")
    if (conditionScript) sb.append(" condition=\"${conditionScript}\"")
    sb.append("><widgets></widgets></section>")
} else {
    sb.append("<${containerType} id=\"${newId}\"")
    if (styleClass) sb.append(" class=\"${styleClass}\"")
    sb.append("></${containerType}>")
}

String updatedXml = xmlText.replace(" id=\"${parentContainerId}\">", " id=\"${parentContainerId}\">\n        " + sb.toString())
if (updatedXml == xmlText) {
    updatedXml = xmlText.replace("</container>", "    " + sb.toString() + "\n</container>")
}

resRef.putText(updatedXml)
ec.logger.info("📦 [MCP /add-container] Injected <${containerType} id=\"${newId}\"> into ${artifactUri}")

context.artifactUri = artifactUri
context.createdContainerId = newId

def art = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", artifactUri).one()
if (art) {
    def parentWe = ec.entity.find("mantle.work.effort.WorkEffort")
            .condition("agiArtifactId", art.agiArtifactId)
            .condition("workEffortTypeEnumId", "WetIntent")
            .one()

    ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([
        workEffortName: "Added Container (${containerType}): ${newId}",
        parentWorkEffortId: parentWe?.workEffortId,
        agiArtifactId: art.agiArtifactId,
        sourceReferenceId: artifactUri,
        workEffortTypeEnumId: "WetIntent"
    ]).call()
}

String parentUri = artifactUri ?: targetScreenUri ?: screenPath
if (!parentUri) {
    ec.message.addError("Parent screen URI (artifactUri or targetScreenUri) is required.")
    return
}

def resRef = ec.resource.getLocationReference(parentUri)
if (!resRef || !resRef.exists) {
    ec.message.addError("Target artifact XML file does not exist at ${parentUri}")
    return
}

String xmlText = resRef.getText()

// 🎯 1. BATCH HANDLING: If Gemini passed subscreenList (e.g. "ERP,PatientManagement,PatientRecords,StaffMeetings")
List<Map> itemsToBind = []
if (subscreenList) {
    List<String> listParts = subscreenList.split(",")
    listParts.each { part ->
        String name = part.trim()
        if (name.contains("/")) name = name.substring(name.lastIndexOf('/') + 1).replace(".xml", "")
        String loc = part.trim().startsWith("component://") ? part.trim() : "component://nursinghome/screen/nursinghome/${name}.xml"
        boolean isDef = (defaultSubscreen && (defaultSubscreen.contains(name) || defaultSubscreen == name))
        itemsToBind.add([name: name, location: loc, isDefault: isDef])
    }
} else if (subscreenName && subscreenLocation) {
    itemsToBind.add([name: subscreenName, location: subscreenLocation, isDefault: isDefault])
} else {
    ec.message.addError("Must provide either (subscreenName + subscreenLocation) OR subscreenList.")
    return
}

// 🎯 2. PROCESS INJECTIONS
itemsToBind.each { item ->
    String titleAttr = item.name.replaceAll("([a-z])([A-Z])", '$1 $2')
    String itemXml = "<subscreens-item name=\"${item.name}\" location=\"${item.location}\" menu-title=\"${titleAttr}\"/>"

    if (!xmlText.contains("<subscreens")) {
        String defaultAttr = item.isDefault ? " default-item=\"${item.name}\"" : ""
        String subscreensBlock = "\n    <subscreens${defaultAttr}>\n        ${itemXml}\n    </subscreens>\n"
        if (xmlText.contains("<widgets>")) {
            xmlText = xmlText.replace("<widgets>", subscreensBlock + "\n    <widgets>")
        } else {
            xmlText = xmlText.replace("</screen>", subscreensBlock + "</screen>")
        }
    } else {
        if (!xmlText.contains("name=\"${item.name}\"")) {
            xmlText = xmlText.replace("</subscreens>", "    ${itemXml}\n    </subscreens>")
        }
        if (item.isDefault) {
            xmlText = xmlText.replace("<subscreens", "<subscreens default-item=\"${item.name}\"")
        }
    }
}

// 🎯 3. INJECT VIEWPORTS
if (!xmlText.contains("<subscreens-active") && !xmlText.contains("<subscreens-tabs")) {
    xmlText = xmlText.replace("</container>", "    <subscreens-tabs id=\"nursinghome-nav-tabs\"/>\n        <subscreens-active id=\"nursinghome-body-viewport\"/>\n    </container>")
}

resRef.putText(xmlText)
ec.logger.info("🔗 [MCP /bind-subscreen] Successfully bound ${itemsToBind.size()} subscreen(s) to ${parentUri}")
context.artifactUri = parentUri

String rawPath = artifactUri ?: screenPath ?: "AgiWorkspace"
def resourceReference = null

try {
    // 1. Direct location lookup if full component:// URI is supplied
    if (rawPath.startsWith("component://")) {
        resourceReference = ec.resource.getLocationReference(rawPath)
    } 

    // 2. Fallback candidate resolution logic
    if (!resourceReference || !resourceReference.exists) {
        String componentName = "nursinghome"
        String fileName = rawPath

        if (rawPath.contains("/")) {
            def parts = rawPath.split("/")
            componentName = parts[0]
            fileName = parts[1]
        }

        // Try XML screen path
        String xmlLoc = "component://${componentName}/screen/${componentName}/${fileName}.xml"
        resourceReference = ec.resource.getLocationReference(xmlLoc)

        // Try QVT asset path
        if (!resourceReference || !resourceReference.exists) {
            String qvtLoc = "component://${componentName}/screen/${componentName}/assets/${fileName}.qvt.js"
            resourceReference = ec.resource.getLocationReference(qvtLoc)
        }
    }

    if (resourceReference && resourceReference.exists) {
        context.rawXmlContent = resourceReference.getText()
        context.fileLocation = resourceReference.location
        ec.logger.info("⚡ [REST /getRawXml] Successfully retrieved asset at: [${resourceReference.location}]")
    } else {
        context.rawXmlContent = ""
        context.fileLocation = null
    }
} catch (Exception ex) {
    ec.logger.error("Failed to execute flexible dynamic resource extraction", ex)
    context.rawXmlContent = ""
    context.fileLocation = null
}

def resRef = ec.resource.getLocationReference(artifactUri)
if (!resRef || !resRef.exists) {
    ec.message.addError("Screen XML file not found at ${artifactUri}")
    return
}

String xmlText = resRef.getText()

// Construct XML action block based on intent actionType
StringBuilder actionXml = new StringBuilder()
if (actionType == "entity-find") {
    actionXml.append("        <entity-find entity-name=\"${entityName}\" list=\"${listName}\">\n")
    if (filterField && filterValue) {
        actionXml.append("            <econdition field-name=\"${filterField}\" value=\"${filterValue}\"/>\n")
    }
    actionXml.append("            <order-by field-name=\"description\"/>\n")
    actionXml.append("        </entity-find>\n")
}

// Inject into existing <actions> block or construct a new one
if (xmlText.contains("<actions>")) {
    xmlText = xmlText.replace("</actions>", actionXml.toString() + "    </actions>")
} else {
    String fullActionsBlock = "    <actions>\n" + actionXml.toString() + "    </actions>\n"
    if (xmlText.contains("<widgets>")) {
        xmlText = xmlText.replace("<widgets>", fullActionsBlock + "\n    <widgets>")
    } else {
        xmlText = xmlText.replace("</screen>", fullActionsBlock + "</screen>")
    }
}

resRef.putText(xmlText)

// Sync updated XML back into WorkspaceBuffer AST
ec.service.sync().name("org.moqui.ai.AgiWorkspaceServices.parse#XmlToTree")
    .parameter("artifactUri", artifactUri)
    .call()

ec.logger.info("⚡ [add#ActionToScreen] Injected ${actionType} into ${artifactUri}")
context.artifactUri = artifactUri
